// 자동 생성 파일 — 직접 수정 금지. 소스: game.html, 생성: scripts/build-game.js
export const GAME_HTML = "<!doctype html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\n<title>Sharks in the Water!</title>\n<style>\n  html,body{margin:0;padding:0;height:100%;overflow:hidden;background:#052a42;\n    touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}\n  canvas{display:block;position:fixed;inset:0}\n</style>\n</head>\n<body>\n<canvas id=\"c\"></canvas>\n<script>\n'use strict';\n/* =====================================================================\n * Sharks in the Water! — SplitLane easter-egg game (docs/09-sharks-game.md)\n * Single-file canvas 2D, zero dependencies. Runs in RN WebView + browser.\n * ===================================================================== */\n\n/* ---------- config from host app ---------- */\nvar CFG = Object.assign(\n  { stroke: 'free', distance: 50, courseUnit: 'y', character: null },\n  window.GAME_CONFIG || {}\n);\nCFG.distance = Math.max(25, Math.min(1650, +CFG.distance || 50));\n\nfunction send(obj) {\n  try {\n    if (window.ReactNativeWebView) window.ReactNativeWebView.postMessage(JSON.stringify(obj));\n  } catch (e) {}\n}\nfunction vibrate(ms) { try { if (navigator.vibrate) navigator.vibrate(ms); } catch (e) {} }\n\n/* ---------- canvas ---------- */\nvar cv = document.getElementById('c'), ctx = cv.getContext('2d');\nvar W = 0, H = 0, DPR = 1;\nfunction resize() {\n  DPR = Math.min(2, window.devicePixelRatio || 1);\n  W = window.innerWidth; H = window.innerHeight;\n  cv.width = Math.round(W * DPR); cv.height = Math.round(H * DPR);\n  cv.style.width = W + 'px'; cv.style.height = H + 'px';\n  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  gradCache = {};\n}\nwindow.addEventListener('resize', resize);\n\n/* ---------- helpers ---------- */\nvar TAU = Math.PI * 2;\nfunction clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\nfunction lerp(a, b, t) { return a + (b - a) * t; }\nfunction easeOut(t) { return 1 - (1 - t) * (1 - t); }\nfunction easeInOut(t) { return t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }\nfunction rnd(a, b) { return a + Math.random() * (b - a); }\nfunction pick(arr) { return arr[(Math.random() * arr.length) | 0]; }\nfunction fmtTime(ms) {\n  ms = Math.max(0, Math.round(ms));\n  var cs = Math.floor(ms / 10) % 100, s = Math.floor(ms / 1000) % 60, m = Math.floor(ms / 60000);\n  return m + ':' + String(s).padStart(2, '0') + '.' + String(cs).padStart(2, '0');\n}\nfunction fitText(text, weight, px, maxW) {\n  ctx.font = weight + ' ' + px + 'px system-ui,sans-serif';\n  var w = ctx.measureText(text).width;\n  if (w > maxW) ctx.font = weight + ' ' + Math.max(9, Math.floor(px * maxW / w)) + 'px system-ui,sans-serif';\n}\nvar gradCache = {};\nfunction vGrad(key, y0, y1, stops) {\n  if (!gradCache[key]) {\n    var g = ctx.createLinearGradient(0, y0, 0, y1);\n    for (var i = 0; i < stops.length; i++) g.addColorStop(stops[i][0], stops[i][1]);\n    gradCache[key] = g;\n  }\n  return gradCache[key];\n}\n\n/* ---------- characters (docs/09 §5) ---------- */\nvar CHARACTERS = [\n  { id: 'phelps',  name: 'Michael Phelps', flag: '🇺🇸', country: 'USA', gender: 'M', skin: '#e9b98b', cap: '#123a6b', suit: '#0d2b52', trait: 'Butterfly legend' },\n  { id: 'thorpe',  name: 'Ian Thorpe',     flag: '🇦🇺', country: 'AUS', gender: 'M', skin: '#e3a877', cap: '#0a5c36', suit: '#083f26', trait: 'Thorpedo' },\n  { id: 'sun',     name: 'Sun Yang',       flag: '🇨🇳', country: 'CHN', gender: 'M', skin: '#f0c493', cap: '#b3241c', suit: '#7d1611', trait: 'Distance free' },\n  { id: 'park',    name: 'Tae-hwan Park',  flag: '🇰🇷', country: 'KOR', gender: 'M', skin: '#f2cb9a', cap: '#0f4c9a', suit: '#0a3268', trait: 'Marine Boy' },\n  { id: 'hagino',  name: 'Kosuke Hagino',  flag: '🇯🇵', country: 'JPN', gender: 'M', skin: '#f0c99b', cap: '#c9303f', suit: '#8d1f2b', trait: 'IM master' },\n  { id: 'ledecky', name: 'Katie Ledecky',  flag: '🇺🇸', country: 'USA', gender: 'F', skin: '#f3c8a0', cap: '#1d5fb8', suit: '#143f7d', trait: 'Freestyle queen' },\n  { id: 'mckeon',  name: 'Emma McKeon',    flag: '🇦🇺', country: 'AUS', gender: 'F', skin: '#eebd92', cap: '#c99b12', suit: '#8a690a', trait: 'Sprint star' },\n  { id: 'zhang',   name: 'Zhang Yufei',    flag: '🇨🇳', country: 'CHN', gender: 'F', skin: '#f5d0a4', cap: '#d43a86', suit: '#93265c', trait: 'Butterfly ace' },\n  { id: 'kim',     name: 'Seo-yeong Kim',  flag: '🇰🇷', country: 'KOR', gender: 'F', skin: '#f4cf9f', cap: '#7a3fbf', suit: '#532a83', trait: 'Medley racer' },\n  { id: 'ikee',    name: 'Rikako Ikee',    flag: '🇯🇵', country: 'JPN', gender: 'F', skin: '#f3cb9c', cap: '#e0596b', suit: '#9c3846', trait: 'Comeback hero' }\n];\nvar selectedChar = CHARACTERS.find(function (c) { return c.id === CFG.character; }) || null;\n\nvar STROKE_NAME = { free: 'FREESTYLE', back: 'BACKSTROKE', breast: 'BREASTSTROKE', fly: 'BUTTERFLY', im: 'IM' };\nvar IM_ORDER = ['fly', 'back', 'breast', 'free'];\n\n/* ---------- themes (docs/09 §4) ---------- */\nvar THEMES = [\n  { id: 'reef',   name: 'Sunlit Reef',       top: '#2f9fd8', bot: '#0b4d7a', floor: '#d8c58f', accent: '#ff8f6b' },\n  { id: 'kelp',   name: 'Kelp Forest',       top: '#1e8f7e', bot: '#073f45', floor: '#7c9a5e', accent: '#9be26b' },\n  { id: 'wreck',  name: 'Shipwreck Cove',    top: '#2a7fae', bot: '#0a3457', floor: '#a9987b', accent: '#c9a24a' },\n  { id: 'cave',   name: 'Deep Cave',         top: '#123350', bot: '#020d1c', floor: '#3c4257', accent: '#7f7fff' },\n  { id: 'shallows', name: 'Treasure Shallows', top: '#41c4e8', bot: '#0e6f9e', floor: '#ecd9a0', accent: '#ffd75e' }\n];\nfunction themePlanFor(laps) {\n  if (laps <= 1) return [0, 4];\n  if (laps === 2) return [0, 2, 4];\n  if (laps <= 4) return [0, 1, 2, 4];\n  return [0, 1, 2, 3, 4];\n}\n\n/* ---------- input ---------- */\nvar input = {\n  down: false, x0: 0, y0: 0, x: 0, y: 0, t0: 0,\n  swiped: false, holdUsed: false, taps: 0\n};\nvar onTapHandler = null, onSwipeHandler = null;\nfunction holdDur(now) { return input.down && !input.holdUsed ? now - input.t0 : 0; }\n\ncv.addEventListener('pointerdown', function (e) {\n  input.down = true; input.swiped = false; input.holdUsed = false;\n  input.x0 = input.x = e.clientX; input.y0 = input.y = e.clientY;\n  input.t0 = performance.now();\n});\ncv.addEventListener('pointermove', function (e) {\n  if (!input.down) return;\n  input.x = e.clientX; input.y = e.clientY;\n  var dx = input.x - input.x0, dy = input.y - input.y0;\n  var TH = 26;\n  if (!input.swiped && (Math.abs(dx) > TH || Math.abs(dy) > TH)) {\n    input.swiped = true;\n    var dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up');\n    if (onSwipeHandler) onSwipeHandler(dir);\n  }\n});\nfunction endPointer(e) {\n  if (!input.down) return;\n  var dur = performance.now() - input.t0;\n  input.down = false;\n  if (!input.swiped && !input.holdUsed && dur < 260 && onTapHandler) onTapHandler(input.x0, input.y0);\n}\ncv.addEventListener('pointerup', endPointer);\ncv.addEventListener('pointercancel', endPointer);\nwindow.addEventListener('keydown', function (e) {\n  if (e.repeat) {\n    if (e.key === ' ') e.preventDefault();\n    return;\n  }\n  var map = { ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down' };\n  if (map[e.key] && onSwipeHandler) { onSwipeHandler(map[e.key]); e.preventDefault(); }\n  if (e.key === 'Enter' && onTapHandler) onTapHandler(W / 2, H / 2);\n  if (e.key === ' ') { // space acts as press-and-hold\n    input.down = true; input.swiped = true; input.holdUsed = false;\n    input.x0 = input.x = W / 2; input.y0 = input.y = H * 0.7; input.t0 = performance.now();\n    e.preventDefault();\n  }\n});\nwindow.addEventListener('keyup', function (e) {\n  if (e.key === ' ') { input.down = false; }\n});\n\n/* ---------- particles ---------- */\nvar parts = [];\nfunction bubble(x, y, opt) {\n  opt = opt || {};\n  parts.push({ kind: 'bubble', x: x, y: y, vx: opt.vx || rnd(-14, 14), vy: opt.vy || rnd(-70, -30),\n    r: opt.r || rnd(2, 6), life: 0, max: opt.max || rnd(.7, 1.6), a: opt.a || .5 });\n}\nfunction sparkle(x, y, col) {\n  parts.push({ kind: 'spark', x: x, y: y, vx: rnd(-60, 60), vy: rnd(-90, -10),\n    r: rnd(2, 4), life: 0, max: rnd(.4, .8), a: 1, col: col || '#ffd75e' });\n}\nfunction splash(x, y, n) { for (var i = 0; i < n; i++) bubble(x + rnd(-40, 40), y + rnd(-20, 20), { vy: rnd(-160, -40), r: rnd(3, 9), max: rnd(.5, 1.1), a: .8 }); }\nfunction updParts(dt) {\n  for (var i = parts.length - 1; i >= 0; i--) {\n    var p = parts[i];\n    p.life += dt; p.x += p.vx * dt; p.y += p.vy * dt;\n    if (p.kind === 'spark') p.vy += 220 * dt;\n    if (p.life > p.max) parts.splice(i, 1);\n  }\n  if (parts.length > 260) parts.splice(0, parts.length - 260);\n}\nfunction drawParts() {\n  for (var i = 0; i < parts.length; i++) {\n    var p = parts[i], t = 1 - p.life / p.max;\n    ctx.globalAlpha = p.a * t;\n    if (p.kind === 'bubble') {\n      ctx.strokeStyle = '#cdeeff'; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, TAU); ctx.stroke();\n    } else {\n      ctx.fillStyle = p.col;\n      ctx.beginPath(); ctx.arc(p.x, p.y, p.r * t, 0, TAU); ctx.fill();\n    }\n  }\n  ctx.globalAlpha = 1;\n}\n\n/* ---------- ambient fish ---------- */\nvar ambients = [];\nfunction seedAmbients() {\n  ambients = [];\n  for (var i = 0; i < 14; i++) ambients.push({ x: rnd(0, 1), y: rnd(.15, .8), s: rnd(.4, 1), v: rnd(.02, .06) * (Math.random() < .5 ? 1 : -1), hue: rnd(0, 60) });\n}\nseedAmbients();\nfunction drawAmbients(dt, alpha) {\n  ctx.globalAlpha = alpha;\n  for (var i = 0; i < ambients.length; i++) {\n    var f = ambients[i];\n    f.x += f.v * dt; if (f.x > 1.1) f.x = -0.1; if (f.x < -0.1) f.x = 1.1;\n    var x = f.x * W, y = f.y * H, s = 6 * f.s, dir = f.v > 0 ? 1 : -1;\n    ctx.fillStyle = 'hsla(' + (190 + f.hue) + ',60%,75%,.5)';\n    ctx.beginPath();\n    ctx.ellipse(x, y, s * 1.6, s, 0, 0, TAU); ctx.fill();\n    ctx.beginPath();\n    ctx.moveTo(x - dir * s * 1.6, y); ctx.lineTo(x - dir * s * 2.6, y - s * .8); ctx.lineTo(x - dir * s * 2.6, y + s * .8);\n    ctx.closePath(); ctx.fill();\n  }\n  ctx.globalAlpha = 1;\n}\n\n/* =====================================================================\n * Scenes: title → select → brief → race (+shark rock) → boss → sprint\n *         → finish → results | gameover\n * ===================================================================== */\nvar scene = 'title', sceneT = 0;\nfunction setScene(s) { scene = s; sceneT = 0; onTapHandler = null; onSwipeHandler = null; enterScene(s); }\n\nvar race = null, boss = null, sprint = null, results = null, gameoverInfo = null;\nvar serverBoard = null; // injected via window.postResult\n\n/* ---------- race model ---------- */\nvar VIEW = 42;           // yards visible ahead\nvar LANE_XS = 0.30;      // lane spread (fraction of W at player plane)\nvar DEPTH_YS = [0.50, 0.645, 0.79]; // player y (fraction of H) per depth\n\nfunction projScale(dz) { var k = 7.5; return k / (dz + k); }\nfunction proj(lane, depth, dz) {\n  var s = projScale(dz);\n  var hy = H * 0.34, cx = W / 2;\n  return {\n    x: cx + (lane - 1) * W * LANE_XS * s,\n    y: hy + (DEPTH_YS[depth] * H - hy) * s,\n    s: s\n  };\n}\n\nfunction strokeAt(prog, total) {\n  if (CFG.stroke !== 'im') return CFG.stroke;\n  var q = clamp(Math.floor(prog / (total / 4)), 0, 3);\n  return IM_ORDER[q];\n}\n\nfunction startRace() {\n  var laps = clamp(Math.round(CFG.distance / 25), 1, 8);\n  var plan = themePlanFor(laps);\n  race = {\n    total: CFG.distance, laps: laps, lapLen: CFG.distance / laps,\n    prog: 0, prevProg: 0, elapsed: 0, bonus: 0, coins: 0,\n    lane: 1, depth: 1, vLane: 1, vDepth: 1,          // logical + visual (tweened)\n    baseSpeed: 6.4, speedMul: 1,\n    obstacles: [], nextSpawn: 18,\n    plan: plan,\n    stroke: strokeAt(0, CFG.distance), strokeBanner: 0,\n    shark: { state: 'none', t: 0 }, nextSharkAt: [], climbed: false, holdRing: 0,\n    diveWipe: 0, count: 3.6, banner: null, bannerT: 0,\n    dead: false, deadT: 0, deadBy: null,\n    bossDone: false, lapFlash: 0, bank: 0\n  };\n  // shark events: at each theme boundary (except start), clamped inside race\n  for (var i = 1; i < plan.length; i++) {\n    var at = (i / plan.length) * race.total;\n    if (at > 12 && at < race.total * 0.86) race.nextSharkAt.push(at);\n  }\n  if (!race.nextSharkAt.length) race.nextSharkAt.push(race.total * 0.45);\n  setScene('race');\n}\n\nfunction themeIdxAt(prog) {\n  var plan = race.plan;\n  return plan[clamp(Math.floor(prog / (race.total / plan.length)), 0, plan.length - 1)];\n}\nfunction themeMix(prog) { // returns {a,b,t} for blending near boundaries\n  var plan = race.plan, seg = race.total / plan.length;\n  var i = clamp(Math.floor(prog / seg), 0, plan.length - 1);\n  var local = (prog - i * seg) / seg;\n  var t = local > 0.86 && i < plan.length - 1 ? (local - 0.86) / 0.14 : 0;\n  return { a: THEMES[plan[i]], b: THEMES[plan[Math.min(i + 1, plan.length - 1)]], t: t };\n}\nfunction mixCol(c1, c2, t) {\n  if (t <= 0) return c1;\n  function h2r(h) { return [parseInt(h.substr(1, 2), 16), parseInt(h.substr(3, 2), 16), parseInt(h.substr(5, 2), 16)]; }\n  var a = h2r(c1), b = h2r(c2);\n  return 'rgb(' + Math.round(lerp(a[0], b[0], t)) + ',' + Math.round(lerp(a[1], b[1], t)) + ',' + Math.round(lerp(a[2], b[2], t)) + ')';\n}\n\n/* ---------- spawner ---------- */\nfunction spawnWave(at) {\n  var th = THEMES[themeIdxAt(at)].id;\n  var lap = Math.floor(at / race.lapLen);\n  var hard = Math.min(1, lap * 0.16);\n  var r = Math.random();\n  var lane = (Math.random() * 3) | 0, depth = (Math.random() * 3) | 0;\n\n  if (th === 'wreck' && r < 0.34) { // coral gate — one open arch\n    var open = (Math.random() * 3) | 0;\n    race.obstacles.push({ type: 'gate', at: at, open: open });\n    return 7.5;\n  }\n  if (th === 'wreck' || th === 'shallows') {\n    if (r < 0.62) { // treasure line\n      var n = 3 + ((Math.random() * 3) | 0);\n      for (var i = 0; i < n; i++)\n        race.obstacles.push({ type: Math.random() < .22 ? 'gem' : 'coin', at: at + i * 1.7, lane: lane, depth: depth, got: false });\n      return n * 1.7 + 3.5;\n    }\n  }\n  if (th === 'kelp' && r < 0.4) { // kelp columns block a lane at all depths\n    race.obstacles.push({ type: 'kelp', at: at, lane: lane });\n    return 6;\n  }\n  if (th === 'cave' && r < 0.35) { // urchin cluster on floor\n    race.obstacles.push({ type: 'urchin', at: at, lane: lane, depth: 2 });\n    if (Math.random() < .5 + hard) race.obstacles.push({ type: 'urchin', at: at + 1.2, lane: (lane + 1) % 3, depth: 2 });\n    return 5.5;\n  }\n  if (r < 0.5) { // jellyfish (blocks cell + one above)\n    race.obstacles.push({ type: 'jelly', at: at, lane: lane, depth: Math.max(1, depth) });\n    if (Math.random() < 0.35 + hard) race.obstacles.push({ type: 'jelly', at: at + 1.5, lane: (lane + 2) % 3, depth: 1 });\n    return 6;\n  }\n  if (r < 0.75) { // pufferfish\n    race.obstacles.push({ type: 'puffer', at: at, lane: lane, depth: depth, ph: rnd(0, TAU) });\n    return 5.5;\n  }\n  race.obstacles.push({ type: 'eel', at: at, lane: Math.min(lane, 1), depth: depth }); // blocks 2 adjacent lanes\n  return 6.5;\n}\n\n/* ---------- collision cells ---------- */\nfunction blockedCells(o) {\n  switch (o.type) {\n    case 'jelly': return [[o.lane, o.depth], [o.lane, o.depth - 1]];\n    case 'puffer': return [[o.lane, o.depth]];\n    case 'urchin': return [[o.lane, 2]];\n    case 'kelp': return [[o.lane, 0], [o.lane, 1], [o.lane, 2]];\n    case 'eel': return [[o.lane, o.depth], [o.lane + 1, o.depth]];\n    case 'gate':\n      var cells = [];\n      for (var l = 0; l < 3; l++) if (l !== o.open) for (var d = 0; d < 3; d++) cells.push([l, d]);\n      return cells;\n  }\n  return [];\n}\n\n/* ---------- race update ---------- */\nfunction updateRace(dt) {\n  var r = race;\n  if (r.count > 0) { r.count -= dt; if (r.count <= 0) { r.banner = 'GO!'; r.bannerT = 0.8; } return; }\n  if (r.dead) {\n    r.deadT += dt;\n    if (r.deadT > 1.4) { gameoverInfo = { by: r.deadBy, timeMs: r.elapsed * 1000, coins: r.coins }; setScene('gameover'); }\n    return;\n  }\n\n  r.elapsed += dt;\n  var sh = r.shark;\n\n  /* hold: climb / dive */\n  var hd = holdDur(performance.now()) / 1000;\n  r.holdRing = 0;\n  var holdable = (!r.climbed && (sh.state === 'alert' || sh.state === 'looming')) || (r.climbed && sh.state === 'calmed');\n  if (holdable) {\n    r.holdRing = clamp(hd / 1, 0, 1);\n    if (hd >= 1) {\n      input.holdUsed = true;\n      if (!r.climbed) { // climb the rock\n        r.climbed = true; sh.state = 'passing'; sh.t = 0;\n        splash(W / 2, H * 0.55, 26); vibrate(30);\n      } else {          // dive back in\n        r.climbed = false; sh.state = 'none'; sh.t = 0; r.diveWipe = 1;\n        splash(W / 2, H * 0.6, 34); vibrate(20);\n      }\n    }\n  }\n\n  /* shark event state machine */\n  if (sh.state === 'none' && r.nextSharkAt.length && r.prog >= r.nextSharkAt[0]) {\n    r.nextSharkAt.shift(); sh.state = 'looming'; sh.t = 0;\n  }\n  if (sh.state === 'looming') {\n    sh.t += dt;\n    if (sh.t > 3.6) { sh.state = 'alert'; sh.t = 0; r.banner = 'SHARKS IN THE WATER!'; r.bannerT = 2.4; vibrate([60, 60, 60]); }\n  } else if (sh.state === 'alert') {\n    sh.t += dt;\n    if (!r.climbed && sh.t > 2.6) { killPlayer('shark'); return; }\n  } else if (sh.state === 'passing') {\n    sh.t += dt;\n    if (sh.t > 2.6) { sh.state = 'calmed'; sh.t = 0; }\n  } else if (sh.state === 'calmed') {\n    sh.t += dt; // waiting for dive hold\n  }\n  if (r.diveWipe > 0) r.diveWipe = Math.max(0, r.diveWipe - dt * 1.4);\n\n  if (r.climbed) { updParts(dt); return; } // time flows, no progress on the rock\n\n  /* stroke + speed */\n  r.stroke = strokeAt(r.prog, r.total);\n  var lap = Math.floor(r.prog / r.lapLen) + 1;\n  r.speedMul = 1 + (lap - 1) * 0.08;\n  var spd = r.baseSpeed * r.speedMul * (sh.state === 'alert' ? 0.55 : 1);\n  r.prevProg = r.prog;\n  r.prog += spd * dt;\n\n  /* lap banner + IM transitions */\n  var newLap = Math.floor(r.prog / r.lapLen) + 1;\n  if (newLap > lap && newLap <= r.laps) { r.banner = 'LAP ' + newLap + ' / ' + r.laps; r.bannerT = 1.4; r.lapFlash = 1; }\n  var st2 = strokeAt(r.prog, r.total);\n  if (st2 !== r.stroke) { r.banner = STROKE_NAME[st2] + '!'; r.bannerT = 1.6; splash(W / 2, H * .6, 18); r.stroke = st2; }\n\n  /* spawn */\n  if (r.prog + VIEW > r.nextSpawn && r.nextSpawn < r.total * 0.9) {\n    r.nextSpawn += spawnWave(r.nextSpawn) * (1 - Math.min(.35, (lap - 1) * .07));\n  }\n\n  /* boss gate */\n  if (!r.bossDone && r.coins >= 12 && r.prog >= r.total * 0.72) {\n    r.bossDone = true; startBoss(); return;\n  }\n  /* sprint gate */\n  if (r.prog >= r.total * 0.88) { startSprint(); return; }\n\n  /* tween visual lane/depth + bank */\n  var dl = r.lane - r.vLane;\n  r.vLane += dl * Math.min(1, dt * 10);\n  r.bank = lerp(r.bank, dl * 0.5, Math.min(1, dt * 8));\n  r.vDepth += (r.depth - r.vDepth) * Math.min(1, dt * 9);\n\n  /* collisions & pickups */\n  for (var i = r.obstacles.length - 1; i >= 0; i--) {\n    var o = r.obstacles[i];\n    var crossed = r.prevProg < o.at && r.prog >= o.at;\n    if (o.type === 'coin' || o.type === 'gem') {\n      if (!o.got && crossed && o.lane === r.lane && o.depth === r.depth) {\n        o.got = true; r.coins += o.type === 'gem' ? 3 : 1;\n        var pp = proj(o.lane, o.depth, 0);\n        for (var k = 0; k < 8; k++) sparkle(pp.x, pp.y, o.type === 'gem' ? '#7ef3ff' : '#ffd75e');\n        vibrate(12);\n      }\n      if (o.at < r.prog - 4) r.obstacles.splice(i, 1);\n      continue;\n    }\n    if (crossed) {\n      var cells = blockedCells(o);\n      for (var c = 0; c < cells.length; c++)\n        if (cells[c][0] === r.lane && cells[c][1] === r.depth) { killPlayer(o.type); return; }\n    }\n    if (o.at < r.prog - 6) r.obstacles.splice(i, 1);\n  }\n\n  /* swim trail */\n  if (Math.random() < dt * 22) {\n    var p = proj(r.vLane, Math.round(r.vDepth), 0);\n    bubble(p.x + rnd(-16, 16), p.y + rnd(8, 26), { a: .35 });\n  }\n  updParts(dt);\n}\n\nfunction killPlayer(by) {\n  race.dead = true; race.deadT = 0; race.deadBy = by;\n  vibrate([80, 40, 120]);\n  var p = proj(race.vLane, Math.round(race.vDepth), 0);\n  splash(p.x, p.y, 30);\n}\n\n/* ---------- boss (Shark King) ---------- */\nfunction startBoss() {\n  boss = {\n    t: 0, throws: 0, maxThrows: 10, dodged: 0, hit: false, done: false,\n    lane: 1, depth: 1, vLane: 1, vDepth: 1,\n    target: null, telT: 0, proj: null, interval: 1.15\n  };\n  race.banner = 'SHARK KING!'; race.bannerT = 2;\n  setScene('boss');\n}\nfunction updateBoss(dt) {\n  var b = boss; b.t += dt; race.elapsed += dt;\n  b.vLane += (b.lane - b.vLane) * Math.min(1, dt * 12);\n  b.vDepth += (b.depth - b.vDepth) * Math.min(1, dt * 12);\n\n  if (b.done) { if (b.t > 1.6) { setScene('race'); } return; }\n\n  if (!b.target && !b.proj && b.throws < b.maxThrows) {\n    b.target = { lane: (Math.random() * 3) | 0, depth: (Math.random() * 3) | 0 };\n    b.telT = Math.max(0.34, 0.62 - b.throws * 0.03);\n  } else if (b.target) {\n    b.telT -= dt;\n    if (b.telT <= 0) {\n      b.proj = { lane: b.target.lane, depth: b.target.depth, z: 1, kind: pick(['bone', 'urchin', 'ink']) };\n      b.target = null;\n    }\n  } else if (b.proj) {\n    b.proj.z -= dt / Math.max(0.4, 0.62 - b.throws * 0.022);\n    if (b.proj.z <= 0) {\n      b.throws++;\n      if (b.proj.lane === b.lane && b.proj.depth === b.depth) {\n        b.hit = true; b.done = true; b.t = 0;\n        race.banner = 'OUCH! BONUS ENDED'; race.bannerT = 1.8; vibrate(120);\n      } else {\n        b.dodged++; race.bonus += 0.8;\n        sparkle(W / 2, H * 0.3, '#8affc1'); vibrate(15);\n        if (b.throws >= b.maxThrows) {\n          b.done = true; b.t = 0;\n          race.banner = 'DODGED! −' + (b.dodged * 0.8).toFixed(1) + 's BONUS'; race.bannerT = 2.4;\n        }\n      }\n      b.proj = null;\n    }\n  }\n  updParts(dt);\n}\n\n/* ---------- sprint ---------- */\nfunction startSprint() {\n  sprint = { taps: 0, speed: 7.5, sharkGap: 7, done: false, t: 0 };\n  race.banner = 'TAP! TAP! SWIM FOR IT!'; race.bannerT = 2.2;\n  setScene('sprint');\n}\nfunction updateSprint(dt) {\n  var s = sprint; s.t += dt; race.elapsed += dt;\n  s.speed = Math.max(6, s.speed - 2.6 * dt);           // decays — keep tapping\n  var mul = 1 + (race.laps - 1) * 0.04;\n  race.prevProg = race.prog;\n  race.prog += s.speed * mul * dt;\n  var sharkSpd = 8.1 * mul;\n  s.sharkGap += (s.speed * mul - sharkSpd) * dt;\n  if (s.sharkGap <= 0.4) { killRaceInSprint(); return; }\n  if (Math.random() < dt * 30) {\n    var p = proj(1, 1, 0); bubble(p.x + rnd(-30, 30), p.y + rnd(0, 30), { a: .5, vy: rnd(-120, -60) });\n  }\n  if (race.prog >= race.total) { finishRace(); return; }\n  updParts(dt);\n}\nfunction killRaceInSprint() {\n  gameoverInfo = { by: 'shark', timeMs: race.elapsed * 1000, coins: race.coins };\n  vibrate([90, 50, 140]);\n  setScene('gameover');\n}\nfunction finishRace() {\n  var t = Math.max(1000, Math.round((race.elapsed - race.bonus) * 1000));\n  results = { timeMs: t, coins: race.coins, bonus: race.bonus, outcome: 'finish' };\n  send({ type: 'result', outcome: 'finish', timeMs: t, coins: race.coins,\n    stroke: CFG.stroke, distance: CFG.distance, courseUnit: CFG.courseUnit,\n    character: selectedChar ? selectedChar.id : null });\n  setScene('finish');\n}\n\n/* ---------- scene entry ---------- */\nfunction enterScene(s) {\n  if (s === 'title') {\n    onTapHandler = function () { setScene('select'); };\n  } else if (s === 'select') {\n    onTapHandler = selectTap;\n  } else if (s === 'brief') {\n    onTapHandler = function () { startRace(); };\n  } else if (s === 'race') {\n    onSwipeHandler = function (dir) {\n      if (race.dead || race.climbed || race.count > 0) return;\n      if (dir === 'left') race.lane = clamp(race.lane - 1, 0, 2);\n      if (dir === 'right') race.lane = clamp(race.lane + 1, 0, 2);\n      if (dir === 'up') race.depth = clamp(race.depth - 1, 0, 2);\n      if (dir === 'down') race.depth = clamp(race.depth + 1, 0, 2);\n    };\n  } else if (s === 'boss') {\n    onSwipeHandler = function (dir) {\n      if (boss.done) return;\n      if (dir === 'left') boss.lane = clamp(boss.lane - 1, 0, 2);\n      if (dir === 'right') boss.lane = clamp(boss.lane + 1, 0, 2);\n      if (dir === 'up') boss.depth = clamp(boss.depth - 1, 0, 2);\n      if (dir === 'down') boss.depth = clamp(boss.depth + 1, 0, 2);\n    };\n  } else if (s === 'sprint') {\n    onTapHandler = function () {\n      sprint.speed = Math.min(13, sprint.speed + 1.15); sprint.taps++;\n      var p = proj(1, 1, 0); splash(p.x, p.y + 10, 3);\n    };\n  } else if (s === 'finish') {\n    setTimeout(function () { if (scene === 'finish') setScene('results'); }, 2600);\n  } else if (s === 'gameover') {\n    send({ type: 'result', outcome: 'gameover', by: gameoverInfo.by, timeMs: Math.round(gameoverInfo.timeMs),\n      coins: gameoverInfo.coins, stroke: CFG.stroke, distance: CFG.distance,\n      courseUnit: CFG.courseUnit, character: selectedChar ? selectedChar.id : null });\n    setTimeout(function () {\n      if (scene !== 'gameover') return;\n      onTapHandler = gameEndTap;\n    }, 700);\n  } else if (s === 'results') {\n    onTapHandler = gameEndTap;\n  }\n}\nfunction gameEndTap(x, y) {\n  // bottom buttons: retry (left) / exit (right)\n  if (y > H - 120) {\n    if (x < W / 2) { parts = []; startRace(); }\n    else send({ type: 'exit' });\n  }\n}\n\n/* ---------- character select ---------- */\nfunction selectGrid() {\n  var cols = W > H ? 5 : 2, rows = Math.ceil(10 / cols);\n  var pad = 12, topY = H * 0.16, botY = H - 96;\n  var cw = (W - pad * (cols + 1)) / cols, ch = (botY - topY - pad * rows) / rows;\n  return { cols: cols, rows: rows, pad: pad, topY: topY, cw: cw, ch: Math.min(ch, 190) };\n}\nfunction selectTap(x, y) {\n  var g = selectGrid();\n  for (var i = 0; i < CHARACTERS.length; i++) {\n    var col = i % g.cols, row = (i / g.cols) | 0;\n    var cx = g.pad + col * (g.cw + g.pad), cy = g.topY + row * (g.ch + g.pad);\n    if (x >= cx && x <= cx + g.cw && y >= cy && y <= cy + g.ch) { selectedChar = CHARACTERS[i]; vibrate(10); return; }\n  }\n  if (selectedChar && y > H - 88 && Math.abs(x - W / 2) < 130) setScene('brief');\n}\n\n/* =====================================================================\n * Rendering\n * ===================================================================== */\nvar lastTs = 0;\nfunction loop(ts) {\n  var dt = Math.min(0.05, (ts - lastTs) / 1000 || 0.016);\n  lastTs = ts; sceneT += dt;\n\n  if (scene === 'race') updateRace(dt);\n  else if (scene === 'boss') updateBoss(dt);\n  else if (scene === 'sprint') updateSprint(dt);\n  else updParts(dt);\n\n  render(dt);\n  requestAnimationFrame(loop);\n}\n\nfunction render(dt) {\n  ctx.clearRect(0, 0, W, H);\n  if (scene === 'title') drawTitle();\n  else if (scene === 'select') drawSelect();\n  else if (scene === 'brief') drawBrief();\n  else if (scene === 'race') drawRace(dt);\n  else if (scene === 'boss') drawBoss(dt);\n  else if (scene === 'sprint') drawSprint(dt);\n  else if (scene === 'finish') drawFinish();\n  else if (scene === 'gameover') drawGameover();\n  else if (scene === 'results') drawResults();\n}\n\n/* ---------- water background ---------- */\nfunction drawWater(top, bot, floorCol, floorY) {\n  ctx.fillStyle = vGrad('w' + top + bot, 0, H, [[0, top], [1, bot]]);\n  ctx.fillRect(0, 0, W, H);\n  // light rays\n  ctx.save(); ctx.globalAlpha = 0.10;\n  for (var i = 0; i < 4; i++) {\n    var x = ((sceneT * 12 + i * W / 3.2) % (W + 300)) - 150;\n    ctx.fillStyle = '#dff6ff';\n    ctx.beginPath();\n    ctx.moveTo(x, 0); ctx.lineTo(x + 90, 0); ctx.lineTo(x - 60, H); ctx.lineTo(x - 150, H);\n    ctx.closePath(); ctx.fill();\n  }\n  ctx.restore();\n  if (floorY != null) {\n    ctx.fillStyle = floorCol;\n    ctx.beginPath();\n    ctx.moveTo(0, H);\n    ctx.lineTo(0, floorY + 14);\n    ctx.quadraticCurveTo(W * 0.3, floorY - 8, W * 0.55, floorY + 6);\n    ctx.quadraticCurveTo(W * 0.8, floorY + 16, W, floorY);\n    ctx.lineTo(W, H); ctx.closePath(); ctx.fill();\n  }\n}\n\n/* ---------- swimmer (rear view) ---------- */\nfunction drawSwimmer(x, y, s, stroke, phase, ch, opts) {\n  ch = ch || CHARACTERS[0]; opts = opts || {};\n  var sz = 46 * s * (opts.scale || 1);\n  ctx.save();\n  ctx.translate(x, y);\n  if (opts.bank) ctx.rotate(opts.bank * 0.4);\n  var onBack = stroke === 'back';\n  var bob = Math.sin(phase * (stroke === 'fly' || stroke === 'breast' ? 1 : 2)) * sz * (stroke === 'fly' ? 0.14 : 0.05);\n  ctx.translate(0, bob);\n\n  // legs / kick (toward camera = below)\n  ctx.strokeStyle = ch.skin; ctx.lineCap = 'round';\n  ctx.lineWidth = sz * 0.24;\n  if (stroke === 'fly') {\n    var k = Math.sin(phase) * sz * 0.35;\n    ctx.beginPath(); ctx.moveTo(-sz * 0.14, sz * 0.55); ctx.quadraticCurveTo(-sz * 0.14, sz * 0.95, -sz * 0.12 + k * 0.2, sz * 1.25 + k); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(sz * 0.14, sz * 0.55); ctx.quadraticCurveTo(sz * 0.14, sz * 0.95, sz * 0.12 + k * 0.2, sz * 1.25 + k); ctx.stroke();\n  } else if (stroke === 'breast') {\n    var fr = Math.sin(phase) * 0.5 + 0.5; // frog kick spread\n    ctx.beginPath(); ctx.moveTo(-sz * 0.14, sz * 0.55); ctx.lineTo(-sz * (0.2 + fr * 0.45), sz * 1.15); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(sz * 0.14, sz * 0.55); ctx.lineTo(sz * (0.2 + fr * 0.45), sz * 1.15); ctx.stroke();\n  } else {\n    var ka = Math.sin(phase * 2) * sz * 0.3, kb = -ka;\n    ctx.beginPath(); ctx.moveTo(-sz * 0.14, sz * 0.55); ctx.lineTo(-sz * 0.16, sz * 1.2 + ka * 0.4); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(sz * 0.14, sz * 0.55); ctx.lineTo(sz * 0.16, sz * 1.2 + kb * 0.4); ctx.stroke();\n  }\n\n  // torso (swimsuit)\n  ctx.fillStyle = ch.suit;\n  ctx.beginPath();\n  ctx.moveTo(-sz * 0.42, -sz * 0.12);\n  ctx.quadraticCurveTo(0, -sz * 0.3, sz * 0.42, -sz * 0.12);\n  ctx.lineTo(sz * 0.26, sz * 0.66);\n  ctx.quadraticCurveTo(0, sz * 0.82, -sz * 0.26, sz * 0.66);\n  ctx.closePath(); ctx.fill();\n\n  // arms\n  function arm(side, a) { // side -1/1, a = stroke angle 0..1 cycle\n    var sx = side * sz * 0.4, sy = -sz * 0.1;\n    var reach = sz * (0.75 + 0.2 * Math.sin(a * TAU));\n    var ang;\n    if (stroke === 'fly') ang = -1.9 + Math.sin(a * TAU) * 1.5;\n    else if (stroke === 'breast') ang = -0.5 - (Math.sin(a * TAU) * .5 + .5) * 1.4;\n    else ang = -1.9 + Math.sin(a * TAU) * 1.7;\n    var hx = sx + side * Math.cos(ang) * reach * -1, hy = sy + Math.sin(ang) * reach;\n    ctx.strokeStyle = ch.skin; ctx.lineWidth = sz * 0.2;\n    ctx.beginPath(); ctx.moveTo(sx, sy);\n    ctx.quadraticCurveTo(sx + side * sz * 0.5, sy - sz * 0.3, hx, hy);\n    ctx.stroke();\n    if (Math.sin(a * TAU) > 0.7) splashMaybe(x + hx, y + hy);\n  }\n  var sync = stroke === 'fly' || stroke === 'breast';\n  arm(-1, phase / TAU);\n  arm(1, sync ? phase / TAU : phase / TAU + 0.5);\n\n  // head + cap (or face when backstroke)\n  var hy2 = -sz * 0.42;\n  ctx.fillStyle = ch.skin;\n  ctx.beginPath(); ctx.arc(0, hy2, sz * 0.3, 0, TAU); ctx.fill();\n  ctx.fillStyle = ch.cap;\n  ctx.beginPath(); ctx.arc(0, hy2 - sz * 0.03, sz * 0.29, Math.PI, 0); ctx.fill();\n  ctx.fillRect(-sz * 0.29, hy2 - sz * 0.05, sz * 0.58, sz * 0.08);\n  if (onBack) { // goggles facing up\n    ctx.fillStyle = '#183048';\n    ctx.beginPath(); ctx.ellipse(-sz * 0.1, hy2 + sz * 0.06, sz * 0.09, sz * 0.06, 0, 0, TAU); ctx.fill();\n    ctx.beginPath(); ctx.ellipse(sz * 0.1, hy2 + sz * 0.06, sz * 0.09, sz * 0.06, 0, 0, TAU); ctx.fill();\n  } else { // goggle strap\n    ctx.strokeStyle = '#183048'; ctx.lineWidth = sz * 0.06;\n    ctx.beginPath(); ctx.moveTo(-sz * 0.28, hy2); ctx.lineTo(sz * 0.28, hy2); ctx.stroke();\n  }\n  ctx.restore();\n}\nvar splashCooldown = 0;\nfunction splashMaybe(x, y) {\n  if (performance.now() - splashCooldown < 120) return;\n  splashCooldown = performance.now();\n  bubble(x, y, { a: .4, r: rnd(2, 4) });\n}\n\n/* ---------- creatures / obstacles ---------- */\nfunction drawJelly(x, y, s, t) {\n  var r = 30 * s;\n  ctx.save(); ctx.translate(x, y + Math.sin(t * 2) * 6 * s);\n  ctx.fillStyle = 'rgba(255,92,180,.85)';\n  ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, 0);\n  ctx.quadraticCurveTo(r, r * 0.4, r * 0.8, r * 0.42);\n  ctx.lineTo(-r * 0.8, r * 0.42);\n  ctx.quadraticCurveTo(-r, r * 0.4, -r, 0);\n  ctx.closePath(); ctx.fill();\n  ctx.strokeStyle = 'rgba(255,60,160,.8)'; ctx.lineWidth = Math.max(1, 3.5 * s); ctx.lineCap = 'round';\n  for (var i = -2; i <= 2; i++) {\n    ctx.beginPath(); ctx.moveTo(i * r * 0.3, r * 0.42);\n    ctx.quadraticCurveTo(i * r * 0.3 + Math.sin(t * 3 + i) * 8 * s, r * 1.1, i * r * 0.3 + Math.sin(t * 3 + i + 1) * 10 * s, r * 1.7);\n    ctx.stroke();\n  }\n  ctx.restore();\n}\nfunction drawPuffer(x, y, s, t) {\n  var r = (24 + Math.sin(t * 4) * 4) * s;\n  ctx.save(); ctx.translate(x, y);\n  ctx.fillStyle = '#e8c25a';\n  ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();\n  ctx.strokeStyle = '#a8842a'; ctx.lineWidth = Math.max(1, 2 * s);\n  for (var i = 0; i < 10; i++) {\n    var a = i / 10 * TAU;\n    ctx.beginPath(); ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);\n    ctx.lineTo(Math.cos(a) * r * 1.3, Math.sin(a) * r * 1.3); ctx.stroke();\n  }\n  ctx.fillStyle = '#1b2b38';\n  ctx.beginPath(); ctx.arc(-r * 0.35, -r * 0.2, r * 0.12, 0, TAU); ctx.fill();\n  ctx.beginPath(); ctx.arc(r * 0.35, -r * 0.2, r * 0.12, 0, TAU); ctx.fill();\n  ctx.restore();\n}\nfunction drawUrchin(x, y, s, t) {\n  var r = 22 * s;\n  ctx.save(); ctx.translate(x, y);\n  ctx.strokeStyle = '#2b1e3f'; ctx.lineWidth = Math.max(1, 2.4 * s);\n  for (var i = 0; i < 14; i++) {\n    var a = i / 14 * TAU + t * 0.2;\n    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(a) * r * 1.6, Math.sin(a) * r * 1.6); ctx.stroke();\n  }\n  ctx.fillStyle = '#463063';\n  ctx.beginPath(); ctx.arc(0, 0, r, 0, TAU); ctx.fill();\n  ctx.restore();\n}\nfunction drawEel(x, y, s, t, w) {\n  ctx.save(); ctx.translate(x, y);\n  ctx.strokeStyle = '#3f7d4e'; ctx.lineWidth = 18 * s; ctx.lineCap = 'round';\n  ctx.beginPath();\n  for (var i = 0; i <= 10; i++) {\n    var px = -w / 2 + w * i / 10, py = Math.sin(t * 4 + i * 0.9) * 10 * s;\n    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);\n  }\n  ctx.stroke();\n  ctx.fillStyle = '#ffe9a8';\n  ctx.beginPath(); ctx.arc(w / 2, Math.sin(t * 4 + 9) * 10 * s, 11 * s, 0, TAU); ctx.fill();\n  ctx.fillStyle = '#1c2b33';\n  ctx.beginPath(); ctx.arc(w / 2 + 3 * s, Math.sin(t * 4 + 9) * 10 * s - 3 * s, 3 * s, 0, TAU); ctx.fill();\n  ctx.restore();\n}\nfunction drawKelpCol(x, yTop, yBot, s, t) {\n  ctx.strokeStyle = '#2f7d3f'; ctx.lineWidth = 12 * s; ctx.lineCap = 'round';\n  for (var j = -1; j <= 1; j++) {\n    ctx.beginPath();\n    for (var i = 0; i <= 8; i++) {\n      var yy = lerp(yBot, yTop, i / 8);\n      var xx = x + j * 14 * s + Math.sin(t * 1.6 + i * 0.7 + j) * 12 * s * (i / 8);\n      i ? ctx.lineTo(xx, yy) : ctx.moveTo(xx, yy);\n    }\n    ctx.stroke();\n  }\n}\nfunction drawGate(o, t) {\n  // three arches at o.at — open one glows, blocked ones have tentacles\n  for (var l = 0; l < 3; l++) {\n    var top = proj(l, 0, o.at - race.prog), bot = proj(l, 2, o.at - race.prog);\n    var s = top.s, w = 60 * s;\n    var open = l === o.open;\n    ctx.strokeStyle = open ? THEMES[2].accent : '#7d6a52';\n    ctx.lineWidth = 16 * s;\n    ctx.beginPath();\n    ctx.moveTo(top.x - w, bot.y + 20 * s);\n    ctx.lineTo(top.x - w, top.y);\n    ctx.quadraticCurveTo(top.x, top.y - 60 * s, top.x + w, top.y);\n    ctx.lineTo(top.x + w, bot.y + 20 * s);\n    ctx.stroke();\n    if (open) {\n      ctx.save(); ctx.globalAlpha = 0.5 + Math.sin(t * 5) * 0.2;\n      ctx.strokeStyle = '#ffe27a'; ctx.lineWidth = 4 * s;\n      ctx.beginPath(); ctx.arc(top.x, (top.y + bot.y) / 2, w * 0.75, 0, TAU); ctx.stroke();\n      ctx.restore();\n    } else {\n      ctx.strokeStyle = 'rgba(150,70,160,.9)'; ctx.lineWidth = 9 * s; ctx.lineCap = 'round';\n      for (var k = -1; k <= 1; k++) {\n        ctx.beginPath();\n        ctx.moveTo(top.x + k * w * 0.4, top.y - 10 * s);\n        ctx.quadraticCurveTo(top.x + k * w * 0.55 + Math.sin(t * 2 + k) * 10 * s, (top.y + bot.y) / 2, top.x + k * w * 0.3, bot.y);\n        ctx.stroke();\n        // suckers\n        ctx.fillStyle = 'rgba(220,160,230,.9)';\n        ctx.beginPath(); ctx.arc(top.x + k * w * 0.45, (top.y + bot.y) / 2, 3.4 * s, 0, TAU); ctx.fill();\n      }\n    }\n  }\n}\nfunction drawCoin(x, y, s, t, gem) {\n  ctx.save(); ctx.translate(x, y);\n  var w = Math.abs(Math.sin(t * 3.5)) * 0.7 + 0.3;\n  if (gem) {\n    ctx.fillStyle = '#59e6ff';\n    ctx.beginPath();\n    ctx.moveTo(0, -16 * s); ctx.lineTo(13 * s * w, 0); ctx.lineTo(0, 16 * s); ctx.lineTo(-13 * s * w, 0);\n    ctx.closePath(); ctx.fill();\n    ctx.strokeStyle = '#bff5ff'; ctx.lineWidth = 2 * s; ctx.stroke();\n  } else {\n    ctx.fillStyle = '#ffcf4d';\n    ctx.beginPath(); ctx.ellipse(0, 0, 13 * s * w, 13 * s, 0, 0, TAU); ctx.fill();\n    ctx.strokeStyle = '#a8781c'; ctx.lineWidth = 2.5 * s; ctx.stroke();\n  }\n  ctx.restore();\n}\nfunction drawShark(x, y, s, opts) {\n  opts = opts || {};\n  ctx.save(); ctx.translate(x, y);\n  if (opts.flip) ctx.scale(-1, 1);\n  ctx.globalAlpha = opts.alpha != null ? opts.alpha : 1;\n  var L = 130 * s;\n  var col = opts.blur ? 'rgba(20,45,66,' + (0.25 + 0.5 * (opts.sharp || 0)) + ')' : '#22434f';\n  // soft silhouette when far (blur substitute: layered alpha)\n  if (opts.blur) {\n    for (var i = 3; i >= 1; i--) {\n      ctx.globalAlpha = 0.1 * (opts.alpha || 1);\n      sharkPath(L * (1 + i * 0.06)); ctx.fillStyle = col; ctx.fill();\n    }\n    ctx.globalAlpha = (0.35 + 0.55 * (opts.sharp || 0)) * (opts.alpha || 1);\n  }\n  sharkPath(L); ctx.fillStyle = col; ctx.fill();\n  if (!opts.blur) { // details\n    ctx.fillStyle = '#dfeef2';\n    ctx.beginPath(); ctx.ellipse(L * 0.18, L * 0.09, L * 0.32, L * 0.1, -0.08, 0, TAU); ctx.fill();\n    ctx.fillStyle = '#0e2530';\n    ctx.beginPath(); ctx.arc(L * 0.4, -L * 0.05, L * 0.028, 0, TAU); ctx.fill();\n    // gills + teeth\n    ctx.strokeStyle = '#16323c'; ctx.lineWidth = L * 0.015;\n    for (var g = 0; g < 3; g++) {\n      ctx.beginPath(); ctx.arc(L * (0.22 + g * 0.035), 0, L * 0.07, -1, 1); ctx.stroke();\n    }\n    if (opts.teeth) {\n      ctx.fillStyle = '#fff';\n      for (var tt = 0; tt < 5; tt++) {\n        ctx.beginPath();\n        var tx = L * (0.34 + tt * 0.03);\n        ctx.moveTo(tx, L * 0.08); ctx.lineTo(tx + L * 0.012, L * 0.13); ctx.lineTo(tx + L * 0.024, L * 0.08);\n        ctx.closePath(); ctx.fill();\n      }\n    }\n  }\n  ctx.restore();\n}\nfunction sharkPath(L) {\n  ctx.beginPath();\n  ctx.moveTo(-L * 0.5, 0);\n  ctx.quadraticCurveTo(-L * 0.2, -L * 0.16, L * 0.15, -L * 0.13);   // back\n  ctx.quadraticCurveTo(L * 0.38, -L * 0.1, L * 0.5, 0);             // nose\n  ctx.quadraticCurveTo(L * 0.3, L * 0.14, -L * 0.1, L * 0.12);      // belly\n  ctx.quadraticCurveTo(-L * 0.3, L * 0.1, -L * 0.5, 0);\n  // tail\n  ctx.moveTo(-L * 0.48, 0);\n  ctx.lineTo(-L * 0.62, -L * 0.18); ctx.lineTo(-L * 0.52, 0); ctx.lineTo(-L * 0.62, L * 0.14);\n  ctx.closePath();\n  // dorsal fin\n  ctx.moveTo(L * 0.02, -L * 0.12);\n  ctx.lineTo(L * 0.08, -L * 0.3); ctx.lineTo(L * 0.18, -L * 0.12);\n  ctx.closePath();\n}\nfunction drawFin(x, y, s) {\n  ctx.fillStyle = '#22434f';\n  ctx.beginPath();\n  ctx.moveTo(x - 18 * s, y); ctx.quadraticCurveTo(x - 4 * s, y - 30 * s, x + 12 * s, y - 26 * s);\n  ctx.quadraticCurveTo(x + 6 * s, y - 10 * s, x + 16 * s, y);\n  ctx.closePath(); ctx.fill();\n  // wake\n  ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(x - 26 * s, y + 2); ctx.quadraticCurveTo(x, y + 8 * s, x + 24 * s, y + 2); ctx.stroke();\n}\nfunction drawIsland(x, y, s) {\n  ctx.save(); ctx.translate(x, y);\n  ctx.fillStyle = '#e8d59a';\n  ctx.beginPath(); ctx.ellipse(0, 0, 90 * s, 26 * s, 0, 0, TAU); ctx.fill();\n  // palm\n  ctx.strokeStyle = '#8a5a2b'; ctx.lineWidth = 7 * s; ctx.lineCap = 'round';\n  ctx.beginPath(); ctx.moveTo(-20 * s, 0); ctx.quadraticCurveTo(-26 * s, -40 * s, -10 * s, -62 * s); ctx.stroke();\n  ctx.strokeStyle = '#2f9d4e'; ctx.lineWidth = 5 * s;\n  for (var i = 0; i < 5; i++) {\n    var a = -0.4 - i * 0.5;\n    ctx.beginPath(); ctx.moveTo(-10 * s, -62 * s);\n    ctx.quadraticCurveTo(-10 * s + Math.cos(a) * 30 * s, -62 * s + Math.sin(a) * 26 * s, -10 * s + Math.cos(a) * 44 * s, -62 * s + Math.sin(a) * 20 * s + 8 * s);\n    ctx.stroke();\n  }\n  // chest\n  ctx.fillStyle = '#8a5a2b'; ctx.fillRect(8 * s, -22 * s, 34 * s, 22 * s);\n  ctx.fillStyle = '#6d4520'; ctx.fillRect(8 * s, -22 * s, 34 * s, 8 * s);\n  ctx.fillStyle = '#ffd75e';\n  ctx.beginPath(); ctx.arc(25 * s, -12 * s, 5 * s, 0, TAU); ctx.fill();\n  ctx.restore();\n}\nfunction drawRock(x, y, s) {\n  ctx.fillStyle = '#6b6154';\n  ctx.beginPath();\n  ctx.moveTo(x - 90 * s, y + 30 * s);\n  ctx.quadraticCurveTo(x - 70 * s, y - 55 * s, x - 10 * s, y - 62 * s);\n  ctx.quadraticCurveTo(x + 60 * s, y - 58 * s, x + 88 * s, y + 30 * s);\n  ctx.closePath(); ctx.fill();\n  ctx.fillStyle = 'rgba(0,0,0,.18)';\n  ctx.beginPath(); ctx.ellipse(x - 20 * s, y - 20 * s, 16 * s, 9 * s, 0.4, 0, TAU); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(x + 30 * s, y - 5 * s, 12 * s, 7 * s, -0.3, 0, TAU); ctx.fill();\n}\n\n/* ---------- theme decorations (parallax at side lanes) ---------- */\nfunction drawThemeDecor(themeA, t) {\n  var id = themeA.id;\n  var floorY = H * 0.82;\n  if (id === 'reef') {\n    for (var i = 0; i < 5; i++) {\n      var x = (i / 5 + 0.08) * W + Math.sin(i * 7) * 20;\n      ctx.fillStyle = i % 2 ? '#ff8f6b' : '#e75f8f';\n      ctx.globalAlpha = 0.75;\n      ctx.beginPath();\n      for (var b = 0; b < 4; b++) ctx.arc(x + b * 8 - 12, floorY + 6 - b * 10, 9, 0, TAU);\n      ctx.fill(); ctx.globalAlpha = 1;\n    }\n  } else if (id === 'kelp') {\n    // 장식 켈프는 플레이 영역 밖(좌우 가장자리)에만 — 장애물 켈프와 혼동 방지\n    var kx = [0.03, 0.09, 0.15, 0.85, 0.91, 0.97];\n    for (var k = 0; k < kx.length; k++) drawKelpCol(kx[k] * W, H * 0.28, floorY + 12, 0.7, t + k);\n  } else if (id === 'wreck') {\n    ctx.save(); ctx.globalAlpha = 0.5; ctx.fillStyle = '#3a2f24';\n    ctx.beginPath();\n    ctx.moveTo(W * 0.06, floorY + 10); ctx.lineTo(W * 0.13, H * 0.5); ctx.lineTo(W * 0.2, floorY + 10);\n    ctx.closePath(); ctx.fill();\n    ctx.fillRect(W * 0.75, H * 0.62, W * 0.2, 12);\n    ctx.fillRect(W * 0.8, H * 0.52, 10, H * 0.3);\n    ctx.restore();\n  } else if (id === 'cave') {\n    ctx.fillStyle = 'rgba(6,10,26,.55)';\n    ctx.beginPath();\n    ctx.moveTo(0, 0); ctx.lineTo(W * 0.22, 0); ctx.quadraticCurveTo(W * 0.06, H * 0.5, W * 0.18, H); ctx.lineTo(0, H);\n    ctx.closePath(); ctx.fill();\n    ctx.beginPath();\n    ctx.moveTo(W, 0); ctx.lineTo(W * 0.78, 0); ctx.quadraticCurveTo(W * 0.94, H * 0.5, W * 0.82, H); ctx.lineTo(W, H);\n    ctx.closePath(); ctx.fill();\n  } else if (id === 'shallows') {\n    ctx.globalAlpha = 0.5;\n    for (var st = 0; st < 7; st++) {\n      var sx = (st / 7 + 0.06) * W, sy = floorY + 8 + (st % 3) * 8;\n      ctx.fillStyle = '#f2b880';\n      ctx.save(); ctx.translate(sx, sy);\n      for (var p5 = 0; p5 < 5; p5++) { ctx.rotate(TAU / 5); ctx.fillRect(-2, -9, 4, 9); }\n      ctx.restore();\n    }\n    ctx.globalAlpha = 1;\n  }\n}\n\n/* ---------- HUD ---------- */\nfunction drawHUD() {\n  var r = race;\n  var lap = clamp(Math.floor(r.prog / r.lapLen) + 1, 1, r.laps);\n  ctx.textAlign = 'left'; ctx.textBaseline = 'top';\n  // lap chip\n  chip(12, 12, 'LAP ' + lap + '/' + r.laps, r.lapFlash > 0 ? '#ffd75e' : 'rgba(4,26,40,.55)');\n  r.lapFlash = Math.max(0, r.lapFlash - 0.02);\n  // stroke chip\n  chip(12, 48, STROKE_NAME[r.stroke], 'rgba(4,26,40,.55)');\n  // time — top center\n  ctx.font = '800 ' + Math.min(34, W * 0.07) + 'px ui-monospace,Menlo,monospace';\n  ctx.textAlign = 'center';\n  ctx.fillStyle = 'rgba(4,26,40,.55)';\n  var tw = ctx.measureText('8:88.88').width + 26;\n  roundRect(W / 2 - tw / 2, 10, tw, 42, 12); ctx.fill();\n  ctx.fillStyle = '#eaf7ff';\n  ctx.fillText(fmtTime((r.elapsed - r.bonus) * 1000), W / 2, 18);\n  // coins — top right\n  ctx.textAlign = 'right'; ctx.font = '800 18px system-ui,sans-serif';\n  ctx.fillStyle = 'rgba(4,26,40,.55)';\n  roundRect(W - 112, 12, 100, 30, 10); ctx.fill();\n  drawCoin(W - 94, 27, 0.9, sceneT, false);\n  ctx.fillStyle = '#ffe9ad'; ctx.fillText(String(r.coins), W - 22, 18);\n  // progress bar\n  var bw = W - 48, bx = 24, by = H - 26;\n  ctx.fillStyle = 'rgba(4,26,40,.5)'; roundRect(bx, by, bw, 10, 5); ctx.fill();\n  ctx.fillStyle = '#5fd6ff'; roundRect(bx, by, bw * clamp(r.prog / r.total, 0, 1), 10, 5); ctx.fill();\n  drawIsland(bx + bw - 4, by - 6, 0.24);\n  drawSwimmerDot(bx + bw * clamp(r.prog / r.total, 0, 1), by + 5);\n  ctx.textAlign = 'left';\n  ctx.font = '700 12px system-ui,sans-serif'; ctx.fillStyle = '#bfe9ff';\n  ctx.fillText(CFG.distance + ' ' + (CFG.courseUnit === 'y' ? 'yd' : 'm') + ' to treasure', bx, by - 18);\n}\nfunction drawSwimmerDot(x, y) {\n  ctx.fillStyle = '#ffd75e';\n  ctx.beginPath(); ctx.arc(x, y, 7, 0, TAU); ctx.fill();\n  ctx.strokeStyle = '#04364e'; ctx.lineWidth = 2; ctx.stroke();\n}\nfunction chip(x, y, text, bg) {\n  ctx.font = '800 15px system-ui,sans-serif';\n  var w = ctx.measureText(text).width + 20;\n  ctx.fillStyle = bg; roundRect(x, y, w, 28, 9); ctx.fill();\n  ctx.fillStyle = '#eaf7ff'; ctx.textAlign = 'left'; ctx.fillText(text, x + 10, y + 7);\n  return w;\n}\nfunction roundRect(x, y, w, h, r) {\n  ctx.beginPath();\n  ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);\n  ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();\n}\nfunction banner(text, alpha, col) {\n  ctx.save(); ctx.globalAlpha = alpha;\n  ctx.font = '900 ' + Math.min(44, W * 0.085) + 'px system-ui,sans-serif';\n  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.lineWidth = 8; ctx.strokeStyle = 'rgba(4,26,40,.85)';\n  ctx.strokeText(text, W / 2, H * 0.3);\n  ctx.fillStyle = col || '#ffd75e';\n  ctx.fillText(text, W / 2, H * 0.3);\n  ctx.restore();\n}\nfunction bigButton(x, y, w, text, primary) {\n  roundRect(x, y, w, 54, 16);\n  ctx.fillStyle = primary ? '#37c0ff' : 'rgba(230,245,255,.14)'; ctx.fill();\n  ctx.font = '800 19px system-ui,sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.fillStyle = primary ? '#03283d' : '#d9f1ff';\n  ctx.fillText(text, x + w / 2, y + 28);\n}\n\n/* ---------- race render ---------- */\nfunction drawRace(dt) {\n  var r = race, mix = themeMix(r.prog);\n  var top = mixCol(mix.a.top, mix.b.top, mix.t), bot = mixCol(mix.a.bot, mix.b.bot, mix.t);\n  var floorCol = mixCol(mix.a.floor, mix.b.floor, mix.t);\n\n  if (r.climbed || r.shark.state === 'passing' || (r.climbed && r.shark.state === 'calmed')) {\n    drawRockScene(dt); return;\n  }\n\n  drawWater(top, bot, floorCol, H * 0.82);\n  drawAmbients(dt, 0.5);\n  drawThemeDecor(mix.a, sceneT);\n\n  // island at horizon grows near the end\n  var isl = clamp((r.prog / r.total - 0.55) / 0.45, 0, 1);\n  if (isl > 0) drawIsland(W / 2, H * 0.335, 0.25 + isl * 0.9);\n\n  // obstacles back-to-front\n  var obs = r.obstacles.slice().sort(function (a, b) { return b.at - a.at; });\n  for (var i = 0; i < obs.length; i++) {\n    var o = obs[i], dz = o.at - r.prog;\n    if (dz < -2 || dz > VIEW) continue;\n    if (o.type === 'gate') { drawGate(o, sceneT); continue; }\n    if (o.type === 'kelp') {\n      var pt = proj(o.lane, 0, dz), pb = proj(o.lane, 2, dz);\n      drawKelpCol(pt.x, pt.y - 30 * pt.s, pb.y + 26 * pb.s, pt.s * 1.5, sceneT);\n      continue;\n    }\n    var p = proj(o.lane, o.depth == null ? 1 : o.depth, dz);\n    if (o.type === 'jelly') drawJelly(p.x, p.y, p.s, sceneT + o.at);\n    else if (o.type === 'puffer') drawPuffer(p.x + Math.sin(sceneT * 2 + o.ph) * 14 * p.s * clamp((dz - 5) / 10, 0, 1), p.y, p.s, sceneT + o.at);\n    else if (o.type === 'urchin') drawUrchin(p.x, p.y + 8 * p.s, p.s, sceneT);\n    else if (o.type === 'eel') drawEel((proj(o.lane, o.depth, dz).x + proj(o.lane + 1, o.depth, dz).x) / 2, p.y, p.s, sceneT + o.at, Math.abs(proj(o.lane + 1, o.depth, dz).x - proj(o.lane, o.depth, dz).x) + 40 * p.s);\n    else if ((o.type === 'coin' || o.type === 'gem') && !o.got) drawCoin(p.x, p.y, p.s, sceneT + o.at, o.type === 'gem');\n  }\n\n  // looming / alert shark\n  var sh = r.shark;\n  if (sh.state === 'looming') {\n    var lt = clamp(sh.t / 3.6, 0, 1);\n    var sp = proj(0.1, 1, lerp(38, 14, lt));\n    drawShark(sp.x, sp.y, sp.s * 1.6, { blur: true, sharp: lt * 0.7, alpha: 0.9, flip: true });\n  } else if (sh.state === 'alert') {\n    var at = clamp(sh.t / 2.6, 0, 1);\n    var ap = proj(lerp(0, 1, at), 1, lerp(13, 1.5, at));\n    drawShark(ap.x, ap.y, ap.s * 1.7, { teeth: at > 0.5, flip: true });\n    // red vignette\n    ctx.save(); ctx.globalAlpha = 0.24 + Math.sin(sceneT * 10) * 0.1;\n    ctx.fillStyle = vGrad('alert', 0, H, [[0, 'rgba(255,40,40,.0)'], [1, 'rgba(255,30,30,.7)']]);\n    ctx.fillRect(0, 0, W, H); ctx.restore();\n  }\n\n  // cave light cone\n  if (mix.a.id === 'cave') {\n    var pp2 = proj(r.vLane, Math.round(r.vDepth), 0);\n    ctx.save();\n    var g = ctx.createRadialGradient(pp2.x, pp2.y - 40, 60, pp2.x, pp2.y - 40, Math.max(W, H) * 0.75);\n    g.addColorStop(0, 'rgba(2,8,20,0)'); g.addColorStop(1, 'rgba(2,8,20,.82)');\n    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n    ctx.restore();\n  }\n\n  // player\n  var pp = proj(r.vLane, 0, 0);\n  var py = lerp(DEPTH_YS[0], DEPTH_YS[2], r.vDepth / 2) * H;\n  var phase = sceneT * (r.stroke === 'breast' ? 4.6 : 6.2);\n  if (!r.dead) drawSwimmer(pp.x, py, 1, r.stroke, phase, selectedChar, { bank: r.bank });\n  else {\n    ctx.save(); ctx.globalAlpha = Math.max(0, 1 - r.deadT);\n    drawSwimmer(pp.x, py + r.deadT * 60, 1, r.stroke, 0, selectedChar, { bank: r.deadT * 2 });\n    ctx.restore();\n  }\n  drawParts();\n\n  // hold ring\n  if (r.holdRing > 0) drawHoldRing(r.holdRing, r.climbed ? 'DIVE!' : 'CLIMB!');\n\n  // countdown\n  if (r.count > 0) {\n    var n = Math.ceil(r.count - 0.6);\n    banner(n > 0 ? String(n) : 'GO!', 1, '#8affc1');\n    ctx.font = '700 16px system-ui,sans-serif'; ctx.textAlign = 'center'; ctx.fillStyle = '#d9f1ff';\n    ctx.fillText('Swipe ⟵ ⟶ ↑ ↓ to swim · hold 1s to climb when sharks come!', W / 2, H * 0.42);\n  }\n  // banner\n  if (r.bannerT > 0) { r.bannerT -= dt; banner(r.banner, clamp(r.bannerT, 0, 1), r.banner && r.banner.indexOf('SHARK') >= 0 ? '#ff6b5e' : '#ffd75e'); }\n\n  // dive wipe (bubbles curtain)\n  if (r.diveWipe > 0) drawBubbleWipe(1 - r.diveWipe);\n  if (r.dead) { ctx.fillStyle = 'rgba(255,40,40,' + Math.max(0, .4 - r.deadT * .3) + ')'; ctx.fillRect(0, 0, W, H); }\n\n  drawHUD();\n}\nfunction drawHoldRing(t, label) {\n  var x = input.down ? input.x : W / 2, y = input.down ? input.y - 70 : H * 0.5;\n  ctx.save();\n  ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 7;\n  ctx.beginPath(); ctx.arc(x, y, 34, 0, TAU); ctx.stroke();\n  ctx.strokeStyle = '#ffd75e';\n  ctx.beginPath(); ctx.arc(x, y, 34, -Math.PI / 2, -Math.PI / 2 + t * TAU); ctx.stroke();\n  ctx.font = '800 14px system-ui,sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.fillStyle = '#ffe9ad'; ctx.fillText(label, x, y + 56);\n  ctx.restore();\n}\nfunction drawBubbleWipe(t) {\n  // t 0→1 curtain rises\n  ctx.save();\n  var yy = H * (1 - t * 1.3);\n  for (var i = 0; i < 40; i++) {\n    var bx = (i / 40) * W + Math.sin(i * 13.3) * 14;\n    var by = yy + Math.sin(i * 7.7) * 60 + 40;\n    var br = 14 + Math.abs(Math.sin(i * 3)) * 26;\n    ctx.fillStyle = 'rgba(214,240,255,.85)';\n    ctx.beginPath(); ctx.arc(bx, by, br, 0, TAU); ctx.fill();\n  }\n  ctx.fillStyle = 'rgba(214,240,255,.92)';\n  ctx.fillRect(0, yy + 60, W, H);\n  ctx.restore();\n}\n\n/* ---------- rock scene (climbed) ---------- */\nfunction drawRockScene(dt) {\n  var r = race, sh = r.shark;\n  // above water: sky + sea\n  ctx.fillStyle = vGrad('sky', 0, H * 0.5, [[0, '#8fd8ff'], [1, '#d8f2ff']]);\n  ctx.fillRect(0, 0, W, H * 0.5);\n  ctx.fillStyle = vGrad('sea', H * 0.5, H, [[0, '#2f9fd8'], [1, '#0b4d7a']]);\n  ctx.fillRect(0, H * 0.5, W, H * 0.5);\n  // waves\n  ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 2;\n  for (var i = 0; i < 3; i++) {\n    ctx.beginPath();\n    for (var x = 0; x <= W; x += 14)\n      ctx.lineTo(x, H * 0.5 + 6 + i * 26 + Math.sin(x / 46 + sceneT * 2 + i) * 4);\n    ctx.stroke();\n  }\n  // distant island\n  drawIsland(W * 0.82, H * 0.47, 0.5);\n  // rock + player standing\n  drawRock(W / 2, H * 0.62, 1.1);\n  drawStanding(W / 2, H * 0.47, 1, selectedChar);\n  // circling fins\n  var n = sh.state === 'passing' ? 3 : sh.state === 'calmed' && sh.t < 1.4 ? 2 : 0;\n  for (var f = 0; f < n; f++) {\n    var a = sceneT * 1.4 + f * 2.1;\n    drawFin(W / 2 + Math.cos(a) * W * 0.3, H * 0.62 + Math.sin(a) * 26 + 30, 1);\n  }\n  if (sh.state === 'calmed' && sh.t >= 1.2) {\n    ctx.font = '800 20px system-ui,sans-serif'; ctx.textAlign = 'center';\n    ctx.fillStyle = '#04364e';\n    ctx.fillText('Coast is clear — hold 1s to dive back in!', W / 2, H * 0.16);\n  } else {\n    ctx.font = '800 20px system-ui,sans-serif'; ctx.textAlign = 'center';\n    ctx.fillStyle = '#a33';\n    ctx.fillText('Whew! Wait for the sharks to pass…', W / 2, H * 0.16);\n  }\n  if (r.holdRing > 0) drawHoldRing(r.holdRing, 'DIVE!');\n  drawParts();\n  drawHUD();\n}\nfunction drawStanding(x, y, s, ch) {\n  ch = ch || CHARACTERS[0];\n  var sz = 40 * s;\n  ctx.save(); ctx.translate(x, y);\n  ctx.strokeStyle = ch.skin; ctx.lineCap = 'round'; ctx.lineWidth = sz * 0.22;\n  // legs\n  ctx.beginPath(); ctx.moveTo(-sz * 0.14, sz * 0.5); ctx.lineTo(-sz * 0.2, sz * 1.1); ctx.stroke();\n  ctx.beginPath(); ctx.moveTo(sz * 0.14, sz * 0.5); ctx.lineTo(sz * 0.2, sz * 1.1); ctx.stroke();\n  // body\n  ctx.fillStyle = ch.suit;\n  roundRectAt(-sz * 0.34, -sz * 0.2, sz * 0.68, sz * 0.78, sz * 0.2); ctx.fill();\n  // arms up (phew!)\n  ctx.beginPath(); ctx.moveTo(-sz * 0.34, -sz * 0.05); ctx.lineTo(-sz * 0.7, -sz * 0.6); ctx.stroke();\n  ctx.beginPath(); ctx.moveTo(sz * 0.34, -sz * 0.05); ctx.lineTo(sz * 0.7, -sz * 0.6); ctx.stroke();\n  // head\n  ctx.fillStyle = ch.skin; ctx.beginPath(); ctx.arc(0, -sz * 0.52, sz * 0.28, 0, TAU); ctx.fill();\n  ctx.fillStyle = ch.cap; ctx.beginPath(); ctx.arc(0, -sz * 0.56, sz * 0.27, Math.PI, 0); ctx.fill();\n  ctx.restore();\n}\nfunction roundRectAt(x, y, w, h, r) {\n  ctx.beginPath();\n  ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);\n  ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();\n}\n\n/* ---------- boss render ---------- */\nfunction drawBoss(dt) {\n  drawWater('#123350', '#020d1c', '#3c4257', H * 0.84);\n  drawAmbients(dt, 0.25);\n  var b = boss;\n  // arena shake on impact\n  var shake = b.proj && b.proj.z < 0.15 ? 4 : 0;\n  ctx.save(); ctx.translate(rnd(-shake, shake), rnd(-shake, shake));\n\n  // shark king\n  var kx = W / 2 + Math.sin(sceneT * 0.8) * W * 0.08, ky = H * 0.24;\n  drawShark(kx, ky, 1.9, { teeth: true, flip: Math.sin(sceneT * 0.8) < 0 });\n  // crown\n  ctx.fillStyle = '#ffd75e';\n  ctx.save(); ctx.translate(kx + (Math.sin(sceneT * .8) < 0 ? -1 : 1) * 60, ky - 66);\n  ctx.beginPath();\n  ctx.moveTo(-22, 12); ctx.lineTo(-22, -8); ctx.lineTo(-10, 2); ctx.lineTo(0, -14); ctx.lineTo(10, 2); ctx.lineTo(22, -8); ctx.lineTo(22, 12);\n  ctx.closePath(); ctx.fill();\n  ctx.restore();\n\n  // telegraph target cell\n  if (b.target) {\n    var tp = proj(b.target.lane, b.target.depth, 0);\n    ctx.save(); ctx.globalAlpha = 0.4 + Math.sin(sceneT * 16) * 0.25;\n    ctx.strokeStyle = '#ff6b5e'; ctx.lineWidth = 5;\n    ctx.beginPath(); ctx.arc(tp.x, tp.y, 46, 0, TAU); ctx.stroke();\n    ctx.restore();\n  }\n  // projectile\n  if (b.proj) {\n    var z = b.proj.z * 16;\n    var pp = proj(b.proj.lane, b.proj.depth, z);\n    var ppx = lerp(pp.x, kx, b.proj.z * 0.6), ppy = lerp(pp.y, ky + 30, b.proj.z * 0.8);\n    if (b.proj.kind === 'urchin') drawUrchin(ppx, ppy, pp.s * 1.2, sceneT * 3);\n    else if (b.proj.kind === 'ink') {\n      ctx.fillStyle = 'rgba(30,20,50,.9)';\n      ctx.beginPath(); ctx.arc(ppx, ppy, 26 * pp.s, 0, TAU); ctx.fill();\n    } else {\n      ctx.save(); ctx.translate(ppx, ppy); ctx.rotate(sceneT * 6);\n      ctx.strokeStyle = '#e9e2ce'; ctx.lineWidth = 9 * pp.s; ctx.lineCap = 'round';\n      ctx.beginPath(); ctx.moveTo(-20 * pp.s, 0); ctx.lineTo(20 * pp.s, 0); ctx.stroke();\n      ctx.fillStyle = '#e9e2ce';\n      [[-20, -6], [-20, 6], [20, -6], [20, 6]].forEach(function (q) {\n        ctx.beginPath(); ctx.arc(q[0] * pp.s, q[1] * pp.s, 6 * pp.s, 0, TAU); ctx.fill();\n      });\n      ctx.restore();\n    }\n  }\n\n  // player (goalkeeper)\n  var gp = proj(b.vLane, 0, 0);\n  var gy = lerp(DEPTH_YS[0], DEPTH_YS[2], b.vDepth / 2) * H;\n  drawSwimmer(gp.x, gy, 1, 'free', sceneT * 5, selectedChar, {});\n  ctx.restore();\n\n  // HUD: throws + dodges + bonus\n  chip(12, 12, 'SHARK KING  ' + b.throws + '/' + b.maxThrows, 'rgba(60,8,20,.6)');\n  chip(12, 48, 'BONUS −' + (b.dodged * 0.8).toFixed(1) + 's', 'rgba(4,40,26,.6)');\n  ctx.font = '800 ' + Math.min(34, W * 0.07) + 'px ui-monospace,Menlo,monospace';\n  ctx.textAlign = 'center'; ctx.fillStyle = '#eaf7ff';\n  ctx.fillText(fmtTime((race.elapsed - race.bonus) * 1000), W / 2, 18);\n  if (race.bannerT > 0) { race.bannerT -= dt; banner(race.banner, clamp(race.bannerT, 0, 1), '#ff8f6b'); }\n  drawParts();\n}\n\n/* ---------- sprint render ---------- */\nfunction drawSprint(dt) {\n  drawWater('#41c4e8', '#0e6f9e', '#ecd9a0', H * 0.84);\n  drawAmbients(dt, 0.4);\n  var s = sprint;\n  var isl = clamp((race.prog / race.total - 0.82) / 0.18, 0, 1);\n  drawIsland(W / 2, H * 0.32, 0.5 + isl * 2.2);\n\n  // chasing sharks behind player (bottom, growing when gap small)\n  var closeness = clamp(1 - s.sharkGap / 7, 0, 1);\n  for (var i = 0; i < 3; i++) {\n    var sx = W / 2 + (i - 1) * W * 0.24 + Math.sin(sceneT * 3 + i) * 10;\n    var sy = H * (0.98 + 0.1 * (1 - closeness)) + i * 14;\n    drawShark(sx, sy, 0.9 + closeness * 0.9, { teeth: closeness > 0.5 });\n  }\n  // player\n  var pp = proj(1, 0, 0);\n  drawSwimmer(pp.x, H * 0.6, 1, race.stroke, sceneT * 9, selectedChar, {});\n  drawParts();\n\n  // urgency vignette\n  ctx.fillStyle = 'rgba(255,40,40,' + closeness * 0.28 + ')';\n  ctx.fillRect(0, 0, W, H);\n\n  // HUD + TAP hint\n  drawHUD();\n  ctx.font = '900 ' + Math.min(38, W * 0.08) + 'px system-ui,sans-serif';\n  ctx.textAlign = 'center'; ctx.fillStyle = '#fff';\n  ctx.globalAlpha = 0.75 + Math.sin(sceneT * 12) * 0.25;\n  ctx.fillText('TAP! TAP! TAP!', W / 2, H * 0.42);\n  ctx.globalAlpha = 1;\n  if (race.bannerT > 0) { race.bannerT -= dt; banner(race.banner, clamp(race.bannerT, 0, 1)); }\n}\n\n/* ---------- title / select / brief ---------- */\nfunction drawTitle() {\n  drawWater('#2f9fd8', '#0b4d7a', '#d8c58f', H * 0.86);\n  drawAmbients(0.016, 0.6);\n  drawIsland(W * 0.78, H * 0.3, 1);\n  drawShark(W * 0.3 + Math.sin(sceneT) * 20, H * 0.62, 1.4, { teeth: true, flip: true });\n  if (Math.random() < 0.1) bubble(rnd(0, W), H, { a: .4 });\n  drawParts(); updParts(0.016);\n\n  ctx.textAlign = 'center';\n  ctx.font = '900 ' + Math.min(52, W * 0.1) + 'px system-ui,sans-serif';\n  ctx.lineWidth = 10; ctx.strokeStyle = 'rgba(3,30,46,.9)'; ctx.textBaseline = 'middle';\n  ctx.strokeText('SHARKS IN', W / 2, H * 0.2);\n  ctx.strokeText('THE WATER!', W / 2, H * 0.3);\n  ctx.fillStyle = '#ffd75e';\n  ctx.fillText('SHARKS IN', W / 2, H * 0.2);\n  ctx.fillText('THE WATER!', W / 2, H * 0.3);\n  var sub = CFG.distance + (CFG.courseUnit === 'y' ? ' yd ' : ' m ') + STROKE_NAME[CFG.stroke] + ' — race to the treasure island!';\n  fitText(sub, '700', 16, W * 0.92); ctx.fillStyle = '#d9f1ff';\n  ctx.fillText(sub, W / 2, H * 0.4);\n  ctx.globalAlpha = 0.7 + Math.sin(sceneT * 4) * 0.3;\n  ctx.font = '800 20px system-ui,sans-serif'; ctx.fillStyle = '#8affc1';\n  ctx.fillText('TAP TO START', W / 2, H * 0.86);\n  ctx.globalAlpha = 1;\n}\nfunction drawSelect() {\n  drawWater('#25709c', '#0a3050', null, null);\n  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.font = '900 ' + Math.min(26, W * 0.055) + 'px system-ui,sans-serif';\n  ctx.fillStyle = '#eaf7ff';\n  ctx.fillText('CHOOSE YOUR SWIMMER', W / 2, H * 0.08);\n\n  var g = selectGrid();\n  for (var i = 0; i < CHARACTERS.length; i++) {\n    var ch = CHARACTERS[i];\n    var col = i % g.cols, row = (i / g.cols) | 0;\n    var x = g.pad + col * (g.cw + g.pad), y = g.topY + row * (g.ch + g.pad);\n    var sel = selectedChar === ch;\n    roundRect(x, y, g.cw, g.ch, 14);\n    ctx.fillStyle = sel ? 'rgba(90,200,255,.28)' : 'rgba(230,245,255,.09)'; ctx.fill();\n    if (sel) { ctx.strokeStyle = '#5fd6ff'; ctx.lineWidth = 3; roundRect(x, y, g.cw, g.ch, 14); ctx.stroke(); }\n    // avatar\n    var ax = x + g.cw / 2, ay = y + g.ch * 0.34, ar = Math.min(g.cw, g.ch) * 0.2;\n    ctx.fillStyle = ch.skin; ctx.beginPath(); ctx.arc(ax, ay, ar, 0, TAU); ctx.fill();\n    ctx.fillStyle = ch.cap; ctx.beginPath(); ctx.arc(ax, ay - ar * 0.12, ar * 0.97, Math.PI, 0); ctx.fill();\n    ctx.strokeStyle = '#183048'; ctx.lineWidth = Math.max(2, ar * 0.16);\n    ctx.beginPath(); ctx.moveTo(ax - ar * 0.9, ay - ar * 0.05); ctx.lineTo(ax + ar * 0.9, ay - ar * 0.05); ctx.stroke();\n    ctx.fillStyle = '#183048';\n    ctx.beginPath(); ctx.ellipse(ax - ar * 0.35, ay + ar * 0.1, ar * 0.22, ar * 0.16, 0, 0, TAU); ctx.fill();\n    ctx.beginPath(); ctx.ellipse(ax + ar * 0.35, ay + ar * 0.1, ar * 0.22, ar * 0.16, 0, 0, TAU); ctx.fill();\n    // texts\n    ctx.font = '800 ' + Math.max(11, Math.min(15, g.cw * 0.09)) + 'px system-ui,sans-serif';\n    ctx.fillStyle = '#eaf7ff';\n    ctx.fillText(ch.name, x + g.cw / 2, y + g.ch * 0.66);\n    ctx.font = '700 ' + Math.max(10, Math.min(13, g.cw * 0.08)) + 'px system-ui,sans-serif';\n    ctx.fillStyle = '#9fd2ef';\n    ctx.fillText(ch.flag + ' ' + ch.country + ' · ' + (ch.gender === 'M' ? '♂' : '♀'), x + g.cw / 2, y + g.ch * 0.8);\n    ctx.fillStyle = '#7fb8d8'; ctx.font = 'italic 600 ' + Math.max(9, Math.min(12, g.cw * 0.07)) + 'px system-ui,sans-serif';\n    ctx.fillText(ch.trait, x + g.cw / 2, y + g.ch * 0.92);\n  }\n  if (selectedChar) bigButton(W / 2 - 130, H - 76, 260, 'DIVE IN  ▶', true);\n  else {\n    ctx.font = '700 15px system-ui,sans-serif'; ctx.fillStyle = '#9fd2ef';\n    ctx.fillText('Tap a swimmer to select', W / 2, H - 50);\n  }\n}\nfunction drawBrief() {\n  drawWater('#2f9fd8', '#0b4d7a', '#d8c58f', H * 0.86);\n  drawAmbients(0.016, 0.5); updParts(0.016); drawParts();\n  drawIsland(W * 0.5, H * 0.28, 1.4);\n  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  var lines = [\n    'Whoah… look at that treasure!',\n    'Swim ' + CFG.distance + (CFG.courseUnit === 'y' ? ' yards' : ' meters') + ' of ' + STROKE_NAME[CFG.stroke] + ' to the island!',\n    '',\n    '🌊  Swipe ⟵ ⟶ ↑ ↓ to dodge sea creatures',\n    '🪸  Only ONE coral arch is open — watch for tentacles!',\n    '🦈  Sharks look blurry far away… when the alarm sounds,',\n    'HOLD 1 second to climb on a rock!',\n    '💰  Grab 12+ coins to challenge the SHARK KING (time bonus!)'\n  ];\n  ctx.font = '800 ' + Math.min(22, W * 0.045) + 'px system-ui,sans-serif';\n  ctx.fillStyle = '#ffd75e';\n  ctx.fillText(lines[0], W / 2, H * 0.46);\n  ctx.fillStyle = '#eaf7ff';\n  for (var i = 1; i < lines.length; i++) {\n    fitText(lines[i], '700', Math.min(16, W * 0.036), W * 0.94);\n    ctx.fillText(lines[i], W / 2, H * 0.46 + 34 + i * 26);\n  }\n  ctx.globalAlpha = 0.7 + Math.sin(sceneT * 4) * 0.3;\n  ctx.font = '800 20px system-ui,sans-serif'; ctx.fillStyle = '#8affc1';\n  ctx.fillText(\"LET'S GO — TAP!\", W / 2, H * 0.92);\n  ctx.globalAlpha = 1;\n}\n\n/* ---------- finish / gameover / results ---------- */\nfunction drawFinish() {\n  drawWater('#41c4e8', '#0e6f9e', '#ecd9a0', H * 0.8);\n  var t = clamp(sceneT / 1.2, 0, 1);\n  drawIsland(W / 2, H * 0.42, 1.6 + t);\n  // treasure burst\n  if (Math.random() < 0.4) sparkle(W / 2 + rnd(-120, 120), H * 0.45 + rnd(-30, 30), pick(['#ffd75e', '#7ef3ff', '#ff9de2']));\n  updParts(0.016); drawParts();\n  drawStanding(W / 2 - 60, H * 0.42, 1.1, selectedChar);\n  banner('WE MADE IT!', 1, '#ffd75e');\n  ctx.font = '800 26px ui-monospace,Menlo,monospace'; ctx.textAlign = 'center';\n  ctx.fillStyle = '#eaf7ff';\n  ctx.fillText(fmtTime(results.timeMs), W / 2, H * 0.62);\n}\nfunction drawGameover() {\n  drawWater('#571f2b', '#160309', null, null);\n  drawShark(W / 2, H * 0.3 + Math.sin(sceneT * 2) * 8, 2.2, { teeth: true });\n  banner(gameoverInfo.by === 'shark' ? 'SHARK GOT YOU!' : 'WIPEOUT!', 1, '#ff6b5e');\n  ctx.textAlign = 'center';\n  ctx.font = '700 16px system-ui,sans-serif'; ctx.fillStyle = '#f3c9c9';\n  ctx.fillText('Coins collected: ' + gameoverInfo.coins + '  ·  ' + fmtTime(gameoverInfo.timeMs), W / 2, H * 0.52);\n  if (sceneT > 0.7) {\n    bigButton(24, H - 90, W / 2 - 36, 'TRY AGAIN', true);\n    bigButton(W / 2 + 12, H - 90, W / 2 - 36, 'EXIT', false);\n  }\n}\nfunction drawResults() {\n  drawWater('#25709c', '#0a3050', null, null);\n  drawAmbients(0.016, 0.3);\n  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.font = '900 ' + Math.min(30, W * 0.06) + 'px system-ui,sans-serif';\n  ctx.fillStyle = '#ffd75e';\n  ctx.fillText('🏆 TREASURE CLAIMED!', W / 2, H * 0.09);\n\n  ctx.font = '800 ' + Math.min(46, W * 0.11) + 'px ui-monospace,Menlo,monospace';\n  ctx.fillStyle = '#eaf7ff';\n  ctx.fillText(fmtTime(results.timeMs), W / 2, H * 0.19);\n  ctx.font = '700 14px system-ui,sans-serif'; ctx.fillStyle = '#9fd2ef';\n  ctx.fillText(CFG.distance + (CFG.courseUnit === 'y' ? 'yd' : 'm') + ' ' + STROKE_NAME[CFG.stroke]\n    + '  ·  💰 ' + results.coins + '  ·  boss bonus −' + results.bonus.toFixed(1) + 's', W / 2, H * 0.25);\n\n  if (serverBoard) {\n    var me = serverBoard.me;\n    if (me) {\n      // badge medallion\n      var bx = W / 2, by = H * 0.36, br = 40;\n      ctx.fillStyle = badgeColor(me.badge);\n      ctx.beginPath(); ctx.arc(bx, by, br, 0, TAU); ctx.fill();\n      ctx.strokeStyle = 'rgba(255,255,255,.7)'; ctx.lineWidth = 4;\n      ctx.beginPath(); ctx.arc(bx, by, br - 4, 0, TAU); ctx.stroke();\n      ctx.font = '900 ' + (me.badge.length > 2 ? 20 : 26) + 'px system-ui,sans-serif';\n      ctx.fillStyle = '#08283c'; ctx.fillText(me.badge, bx, by + 1);\n      ctx.font = '700 15px system-ui,sans-serif'; ctx.fillStyle = '#eaf7ff';\n      ctx.fillText('Rank #' + me.rank + ' of ' + me.total + '  ·  top ' + me.percentile.toFixed(1) + '%', W / 2, by + br + 22);\n    }\n    var items = serverBoard.items || [];\n    var ly = H * 0.5;\n    ctx.font = '800 14px system-ui,sans-serif'; ctx.fillStyle = '#9fd2ef';\n    ctx.fillText('— LEADERBOARD —', W / 2, ly - 12);\n    ctx.font = '700 14px ui-monospace,Menlo,monospace';\n    for (var i = 0; i < Math.min(8, items.length); i++) {\n      var it = items[i], mine = me && it.rank === me.rank && it.timeMs === me.timeMs;\n      ctx.fillStyle = mine ? '#ffd75e' : '#d9ecf7';\n      var nm = (it.displayName || 'Swimmer').slice(0, 14);\n      ctx.textAlign = 'left';\n      ctx.fillText('#' + it.rank + '  ' + nm, W * 0.14, ly + 10 + i * 22);\n      ctx.textAlign = 'right';\n      ctx.fillText(fmtTime(it.timeMs) + '  ' + it.badge, W * 0.86, ly + 10 + i * 22);\n    }\n    ctx.textAlign = 'center';\n  } else {\n    ctx.font = '700 14px system-ui,sans-serif'; ctx.fillStyle = '#7fa8c8';\n    ctx.fillText(window.ReactNativeWebView ? 'Sign in to the AI Coach account to join the leaderboard!' : 'Leaderboard available in the app', W / 2, H * 0.42);\n    // local badge tease\n    ctx.font = '700 15px system-ui,sans-serif'; ctx.fillStyle = '#9fd2ef';\n    ctx.fillText('Great swim, ' + (selectedChar ? selectedChar.name : 'champ') + '! ' + (selectedChar ? selectedChar.flag : ''), W / 2, H * 0.5);\n  }\n  bigButton(24, H - 90, W / 2 - 36, 'RACE AGAIN', true);\n  bigButton(W / 2 + 12, H - 90, W / 2 - 36, 'EXIT', false);\n}\nfunction badgeColor(b) {\n  return { AAAA: '#ffd75e', AAA: '#e8e8ef', AA: '#e2a55f', A: '#7ef3ff', BB: '#8affc1', B: '#b9c7d8' }[b] || '#b9c7d8';\n}\n\n/* ---------- host → game bridge ---------- */\nwindow.postResult = function (data) {\n  try { serverBoard = typeof data === 'string' ? JSON.parse(data) : data; } catch (e) {}\n};\n\n/* 테스트/자동화 훅 (읽기 전용) — playwright 스모크가 사용 */\nwindow.__debug = {\n  get scene() { return scene; },\n  get race() { return race; },\n  get boss() { return boss; },\n  get sprint() { return sprint; },\n  get results() { return results; },\n  blockedCells: blockedCells\n};\n\nsetScene('title');\nresize();\nrequestAnimationFrame(loop);\n</script>\n</body>\n</html>\n";
